Replace the `load` and refresh wiring in `public/dashboard.js` with:

```js
let lastStamp = null;

async function poll() {
  try {
    const { rows, computed_at } = await (await fetch('/api/metrics')).json();
    // Skip empty results (table mid-rewrite) and unchanged snapshots.
    if (!rows.length || computed_at === lastStamp) return;
    lastStamp = computed_at;
    render(rows);
    document.getElementById('stamp').textContent = new Date(computed_at).toLocaleTimeString();
  } catch (err) {
    // Network error or timeout: keep the last good render.
  } finally {
    setTimeout(poll, 15000);
  }
}

window.addEventListener('load', poll);
```

The chained `setTimeout` means a slow request can't stack up with the next one. Remove the refresh button's click listener, because it now points at a function that no longer exists. The button markup can go too.

