const { currentToken } = require('/tmp/tmp167jyvve/auth.js');

const mkStore = () => {
  const m = new Map();
  return { get: (k) => m.get(k), set: (k, v) => m.set(k, v), clear: () => m.clear(), m };
};
const expired = (v) => ({ value: v, expiresAt: 0 });
const seen = [];
let respond = null;
globalThis.fetch = (url, opts) => {
  seen.push(JSON.parse(opts.body).refresh_token);
  return respond();
};

(async () => {
  // 1. Concurrent calls with an expired token
  respond = async () => ({ status: 200, ok: true, json: async () => ({ access_token: 'NEW', expires_in: 3600 }) });
  const s = mkStore();
  s.set('access', expired('OLD'));
  s.set('refresh', { value: 'RT1' });
  const r = await Promise.all([currentToken(s), currentToken(s), currentToken(s)]);
  console.log('1. concurrent results:', r, 'fetch calls:', seen.length);

  // 2. Two different stores at the same time (module-level inFlight)
  seen.length = 0;
  const a = mkStore(); a.set('access', expired('A')); a.set('refresh', { value: 'RT_A' });
  const b = mkStore(); b.set('access', expired('B')); b.set('refresh', { value: 'RT_B' });
  const [ta, tb] = await Promise.all([currentToken(a), currentToken(b)]);
  console.log('2. two stores -> tokens:', ta, tb, 'refresh tokens sent:', seen, 'b.access now:', b.get('access')?.value);

  // 3. Refresh endpoint returns 400 invalid_grant (RFC 6749 style)
  seen.length = 0;
  respond = async () => ({ status: 400, ok: false, json: async () => ({ error: 'invalid_grant' }) });
  const c = mkStore(); c.set('access', expired('C')); c.set('refresh', { value: 'DEAD' });
  await currentToken(c).catch((e) => console.log('3. error:', e.message));
  console.log('3. after 400, refresh kept:', !!c.get('refresh'), 'access kept:', !!c.get('access'));
  await currentToken(c).catch((e) => console.log('3. second call error:', e.message));
  console.log('3. refresh endpoint hit again:', seen.length, 'times');

  // 4. Refresh endpoint returns 401
  respond = async () => ({ status: 401, ok: false });
  const d = mkStore(); d.set('access', expired('D')); d.set('refresh', { value: 'DEAD' });
  await currentToken(d).catch((e) => console.log('4. error:', e.message));
  console.log('4. after 401, store size:', d.m.size);

  // 5. Network failure
  respond = () => Promise.reject(new TypeError('fetch failed'));
  const e5 = mkStore(); e5.set('access', expired('E')); e5.set('refresh', { value: 'RT_E' });
  await currentToken(e5).catch((e) => console.log('5. error:', e.message));
  console.log('5. after network error, store size:', e5.m.size);
})();
EOF
