1. **`api/metrics.js`**: derive the ETag from `computed_at`. Instances share no memory, but every instance reads the same rollup table, so they all produce the same tag. Return 304 when `If-None-Match` matches, and change `Cache-Control` from `no-store` to `no-cache`, since `no-store` stops the browser from keeping the validator.

   ```js
   const db = require('../db');

   module.exports = async (req, res) => {
     const rows = await db.currentRollup();
     const computedAt = rows[0] && rows[0].computed_at;
     if (!computedAt) return res.status(503).json({ error: 'rollup empty' });
     const etag = `"${new Date(computedAt).getTime()}"`;
     res.setHeader('Cache-Control', 'no-cache');
     res.setHeader('ETag', etag);
     if (req.headers['if-none-match'] === etag) return res.status(304).end();
     res.json({ rows, computed_at: computedAt });
   };
   ```

